package dev.jpa.team1.recommend.recommendproduct; import lombok.*;
@Getter @Setter @NoArgsConstructor @AllArgsConstructor
public class RecommendProductResponseDto {private Long id;private Long recommendationId;private Long productId;private Long productColorId;private String itemType;private Integer sortOrder;private String reason; public static RecommendProductResponseDto from(RecommendProduct r){return new RecommendProductResponseDto(r.getId(),r.getBeautyRecommendation().getId(),r.getProduct().getId(),r.getProductColor()!=null?r.getProductColor().getId():null,r.getItemType(),r.getSortOrder(),r.getReason());}}
